function homepageExplorerHref(sample,lossesOnly=false){const query=new URLSearchParams;query.set('crate_version',sample.crate_version);if(lossesOnly)query.set('losses_only','true');query.set('sample',comparisonSelectionKey(sample));return `${base}ir-fn-g8r-abc-vs-codegen-yosys-abc/?${query}`}
function bindHomepageExplorerClick(plotId,lossesOnly=false){const plot=byId(plotId);if(!plot||typeof plot.on!=='function')return;if(typeof plot.removeAllListeners==='function')plot.removeAllListeners('plotly_click');plot.on('plotly_click',event=>{const sample=event?.points?.[0]?.customdata;if(sample)location.href=homepageExplorerHref(sample,lossesOnly)})}
function homepagePairPlot(plotId,samples,xTitle,yTitle,xSelect,ySelect,state){const valid=[];for(const sample of samples){const x=comparisonLogValue(xSelect(sample)),y=comparisonLogValue(ySelect(sample));if(x&&y)valid.push({sample,x:x.value,y:y.value,clamped:x.clamped||y.clamped,quadrant:comparisonQuadrant(sample,state)})}const traces=[];if(valid.length){const x=valid.map(row=>row.x),y=valid.map(row=>row.y),both=x.concat(y),min=Math.min(...both),max=Math.max(...both);traces.push({type:'scatter',mode:'markers',x,y,customdata:valid.map(row=>row.sample),text:valid.map(row=>comparisonHover(row.sample,state)+'<br>'+row.quadrant.label),hovertemplate:'%{text}<br>x=%{x}<br>y=%{y}<extra></extra>',marker:{size:6,color:valid.map(row=>row.quadrant.color),opacity:.62}});traces.push({type:'scatter',mode:'lines',x:[min,max],y:[min,max],hoverinfo:'skip',line:{color:'#32f1b2',width:1.1,dash:'dot'}})}const layout=homepagePlotLayout(xTitle,yTitle,true,true),clamped=valid.filter(row=>row.clamped).length;if(!valid.length)layout.annotations=[{text:'No paired IR samples are available',showarrow:false,x:.5,y:.5,xref:'paper',yref:'paper',font:{color:'#8fa9be',size:12}}];else if(clamped)layout.annotations=[{text:`${clamped.toLocaleString()} zero-valued pair${clamped===1?'':'s'} plotted at 1 for log scale`,showarrow:false,x:1,y:1,xanchor:'right',yanchor:'top',xref:'paper',yref:'paper',font:{color:'#8fa9be',size:10},bgcolor:'rgba(11,23,42,.82)'}];return Plotly.react(plotId,traces,layout,comparisonConfig()).then(()=>bindHomepageExplorerClick(plotId))}
function homepageQuadrantPlot(summary,state){const traces=summary.quadrants.length?[{type:'scatter',mode:'markers',x:summary.quadrants.map(row=>row.dx),y:summary.quadrants.map(row=>row.dy),customdata:summary.quadrants.map(row=>row.sample),text:summary.quadrants.map(row=>`${comparisonHover(row.sample,state)}<br>${row.label}`),hovertemplate:'%{text}<br>node delta=%{x}<br>level delta=%{y}<extra></extra>',marker:{size:6,color:summary.quadrants.map(row=>row.color),opacity:.62}}]:[],layout=homepagePlotLayout(`${state.rhs} nodes − ${state.lhs} nodes`,`${state.rhs} levels − ${state.lhs} levels`);layout.shapes=[{type:'line',x0:0,x1:0,xref:'x',y0:0,y1:1,yref:'paper',line:{color:'#5ec9ff',width:1,dash:'dot'}},{type:'line',x0:0,x1:1,xref:'paper',y0:0,y1:0,yref:'y',line:{color:'#5ec9ff',width:1,dash:'dot'}}];layout.annotations=[['Q2 mixed',.13,.93,'#ffd36f'],['Q1 pure win',.87,.93,'#7dff9f'],['Q3 strict loss',.13,.08,'#ff8ea9'],['Q4 mixed',.87,.08,'#5ec9ff']].map(([text,x,y,color])=>({text,showarrow:false,x,y,xref:'paper',yref:'paper',font:{color,size:10}}));return Plotly.react('home-plot-deltas',traces,layout,comparisonConfig()).then(()=>bindHomepageExplorerClick('home-plot-deltas'))}
function homepageLossPlot(summary,state){const valid=summary.quadrants.filter(row=>row.label.startsWith('Q3 strict loss')).map(row=>({sample:row.sample,x:Number(row.sample.ir_node_count),y:Number(row.sample.g8r_product_loss)})).filter(row=>Number.isFinite(row.x)&&row.x>0&&Number.isFinite(row.y)&&row.y>0),traces=valid.length?[{type:'scatter',mode:'markers',x:valid.map(row=>row.x),y:valid.map(row=>row.y),customdata:valid.map(row=>row.sample),text:valid.map(row=>comparisonHover(row.sample,state)),hovertemplate:'%{text}<br>strict product loss=%{y}<extra></extra>',marker:{size:7,color:'#ff8ea9',opacity:.68}}]:[],layout=homepagePlotLayout('IR node count',`${state.lhs} product − ${state.rhs} product`,true,true);if(!valid.length)layout.annotations=[{text:'No positive strict-loss samples',showarrow:false,x:.5,y:.5,xref:'paper',yref:'paper',font:{color:'#8fa9be',size:12}}];return Plotly.react('home-plot-loss',traces,layout,comparisonConfig()).then(()=>bindHomepageExplorerClick('home-plot-loss',true))}
async function homepageOverview(catalog){const root=byId('home-overview');if(!root)return;const status=byId('home-overview-status'),dataset=catalog.datasets.find(value=>value.logical_key===root.dataset.datasetKey);if(!dataset){status.textContent='Homepage comparison data is not available in this snapshot.';root.dataset.rendered='unavailable';return}if(typeof Plotly==='undefined'){status.textContent='The local plotting library could not be loaded.';root.dataset.rendered='unavailable';return}try{const data=await fetch(base+dataset.url).then(response=>{if(!response.ok)throw Error(`${dataset.url} ${response.status}`);return response.json()}),state={lhs:root.dataset.lhsLabel,rhs:root.dataset.rhsLabel},summary=homepageSummary(data.dataset?.samples||[],state);if(!summary.samples.length){status.textContent='No paired IR samples are present in the comparison dataset.';root.dataset.rendered='unavailable';return}const releaseLabel=summary.versions.length<=3?summary.versions.map(version=>`v${version}`).join(' + '):`${summary.versions.length} releases (v${summary.versions[0]}–v${summary.versions.at(-1)})`;byId('home-overview-release').textContent=releaseLabel;byId('home-sample-count').textContent=summary.samples.length.toLocaleString();byId('home-pure-win-count').textContent=summary.pureWins.toLocaleString();byId('home-strict-loss-count').textContent=summary.strictLosses.toLocaleString();byId('home-median-loss').textContent=summary.medianLoss===null?'—':`${summary.medianLoss>0?'+':''}${product(summary.medianLoss)}`;const kinds=[summary.wholeFunctionCount?`${summary.wholeFunctionCount.toLocaleString()} whole-function`:null,summary.mffcCount?`${summary.mffcCount.toLocaleString()} MFFC`:null,summary.k3Count?`${summary.k3Count.toLocaleString()} k3`:null].filter(Boolean).join(', '),warning=byId('home-coverage-warning');warning.hidden=false;warning.textContent=`Coverage notice — showing every currently published paired IR sample across ${releaseLabel}: ${kinds}. Generated subgraphs can overlap and repeated structures across releases remain separate measurements, so points are not statistically independent. The dataset is not bound to exact campaign completeness; aggregates are descriptive, not a release-to-release population estimate.`;byId('home-full-explorer-link').href=`${base}ir-fn-g8r-abc-vs-codegen-yosys-abc/?all_versions=true`;status.textContent=`all published corpus · ${summary.samples.length.toLocaleString()} paired IR samples · ${summary.versions.length.toLocaleString()} crate releases · click a point to inspect evidence`;await Promise.all([homepagePairPlot('home-plot-levels',summary.samples,`${state.lhs} levels`,`${state.rhs} levels`,sample=>sample.g8r_levels,sample=>sample.yosys_abc_levels,state),homepagePairPlot('home-plot-nodes',summary.samples,`${state.lhs} nodes`,`${state.rhs} nodes`,sample=>sample.g8r_nodes,sample=>sample.yosys_abc_nodes,state),homepageQuadrantPlot(summary,state),homepageLossPlot(summary,state)]);root.dataset.rendered='true'}catch(error){status.textContent=`Overview unavailable: ${error}`;root.dataset.rendered='unavailable'}}

async function datasetExplorer(catalog){const select=byId('dataset');if(!select)return;for(const d of catalog.datasets){const o=document.createElement('option');o.value=d.logical_key;o.textContent=`${d.logical_key} (${d.bytes.toLocaleString()} B)`;select.appendChild(o)}const q=new URLSearchParams(location.search).get('key');if(q&&catalog.datasets.some(d=>d.logical_key===q))select.value=q;async function load(){const d=catalog.datasets.find(x=>x.logical_key===select.value);history.replaceState(null,'','?key='+encodeURIComponent(d.logical_key));byId('dataset-meta').textContent=`sha256 ${d.sha256} · ${d.bytes.toLocaleString()} bytes`;const data=await fetch(base+d.url).then(r=>{if(!r.ok)throw Error(`${d.url} ${r.status}`);return r.json()});const found=arrays(data),rows=found[0]?.[1]||[];byId('plot').innerHTML=renderPlot(rows);byId('table').innerHTML=found.length?`<h2>Rows: ${esc(found[0][0])}</h2>${renderTable(rows)}`:'<p class=muted>No tabular row arrays found.</p>';byId('raw').textContent=JSON.stringify(data,null,2)}select.addEventListener('change',load);if(catalog.datasets.length)await load()}
function progressionUnavailable(root,message){root.querySelector('.toolbar').hidden=true;byId('progression-summary').innerHTML='';byId('progression-chart').innerHTML=`<p class=muted>${esc(message)}</p>`;byId('progression-table').innerHTML=''}
async function progression(catalog){const root=byId('progression');if(!root)return;const key=root.dataset.datasetKey,dataset=catalog.datasets.find(d=>d.logical_key===key);if(!dataset){progressionUnavailable(root,'Release progression data is not available in this snapshot.');return}const data=await fetch(base+dataset.url).then(r=>{if(!r.ok)throw Error(`${dataset.url} ${r.status}`);return r.json()}),samples=data.dataset?.samples||[];let generations;try{generations=releaseGenerations(catalog,samples)}catch(error){progressionUnavailable(root,`Release progression data is ambiguous: ${error.message}`);return}const completeGenerations=generations.filter(g=>g.status==='complete'),completeVersions=[...new Set(completeGenerations.map(g=>g.version))].sort(versionCompare);if(completeVersions.length<2){const missingLineage=samples.length&&!samples.some(s=>s.stdlib_root_action_id),degradedCount=generations.length-completeGenerations.length,detail=missingLineage?'This snapshot predates exact run-lineage metadata and must be rebuilt.':completeVersions.length===1?`Only v${completeVersions[0]} has populated complete-run samples.`:'No populated complete-run samples are available.',degraded=degradedCount?` ${degradedCount.toLocaleString()} degraded run generation(s) were excluded because partial populations can bias the result.`:'';progressionUnavailable(root,`At least two populated complete crate releases are needed for a progression comparison. ${detail}${degraded}`);return}const stats=releaseStats(completeGenerations);byId('progression-chart').innerHTML=progressionChart(stats);const baseline=byId('baseline-version'),current=byId('current-version'),options=generations.map(g=>`<option value='${g.run_id}'>v${esc(g.version)} · run ${esc(g.run_id.slice(0,12))} · ${esc(g.status)} · ${g.samples.length.toLocaleString()} samples</option>`).join('');baseline.innerHTML=options;current.innerHTML=options;const preferredByVersion=new Map;for(const generation of completeGenerations)preferredByVersion.set(generation.version,generation);baseline.value=preferredByVersion.get(completeVersions.at(-2)).run_id;current.value=preferredByVersion.get(completeVersions.at(-1)).run_id;const render=()=>renderPair(generations,baseline.value,current.value);baseline.addEventListener('change',render);current.addEventListener('change',render);render()}
async function main(){const catalog=await fetch(base+'catalog.json').then(r=>{if(!r.ok)throw Error(`catalog ${r.status}`);return r.json()});await homepageOverview(catalog);await datasetExplorer(catalog);await progression(catalog);await mffcDiscrepancies(catalog);await comparisonPlots(catalog)}main().catch(e=>{const out=byId('error');if(out)out.textContent=e.stack||e});